import{c as t,Q as n,j as s,m as e}from"./chunks/framework.DOi4mjdC.js";const l="/assets/ND%E6%A0%BC%E5%BC%8FC%E7%9F%A9%E9%98%B5N%E6%96%B9%E5%90%91%E9%9D%9E32%E5%AD%97%E8%8A%82%E5%AF%B9%E9%BD%90%E7%A4%BA%E6%84%8F%E5%9B%BE.BtryVHJB.png",i="/assets/ND%E6%A0%BC%E5%BC%8FC%E7%9F%A9%E9%98%B5N%E6%96%B9%E5%90%9132%E5%AD%97%E8%8A%82%E5%AF%B9%E9%BD%90%E7%A4%BA%E6%84%8F%E5%9B%BE.BK7tnP1Q.png",p="/assets/ND_ALIGN%E6%A0%BC%E5%BC%8FC%E7%9F%A9%E9%98%B5N%E6%96%B9%E5%90%9132%E5%AD%97%E8%8A%82%E5%AF%B9%E9%BD%90%E7%A4%BA%E6%84%8F%E5%9B%BE.B_i92KOT.png",d=JSON.parse('{"title":"矩阵乘输出的N方向对齐","description":"","frontmatter":{},"headers":[{"level":1,"title":"矩阵乘输出的N方向对齐","slug":"矩阵乘输出的n方向对齐"},{"level":2,"title":"功能介绍","slug":"功能介绍"},{"level":2,"title":"使用场景","slug":"使用场景"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"guide/算子实践参考/SIMD算子实现/矩阵编程（高阶API）/特性场景/矩阵乘输出的N方向对齐.md","filePath":"guide/算子实践参考/SIMD算子实现/矩阵编程（高阶API）/特性场景/矩阵乘输出的N方向对齐.md"}'),o={name:"guide/算子实践参考/SIMD算子实现/矩阵编程（高阶API）/特性场景/矩阵乘输出的N方向对齐.md"};function r(c,a,_,m,N,u){return n(),s("div",null,[...a[0]||(a[0]=[e('<h1 id="矩阵乘输出的n方向对齐" tabindex="-1">矩阵乘输出的N方向对齐 <a class="header-anchor" href="#矩阵乘输出的n方向对齐" aria-label="Permalink to &quot;矩阵乘输出的N方向对齐&quot;">​</a></h1><h2 id="功能介绍" tabindex="-1">功能介绍 <a class="header-anchor" href="#功能介绍" aria-label="Permalink to &quot;功能介绍&quot;">​</a></h2><p>矩阵乘输出的N方向对齐，即矩阵乘结果C矩阵按ND_ALIGN格式输出。在Matmul矩阵乘法中，常用的矩阵数据格式有ND、NZ，相关介绍可参考<a href="./../基础知识.html#zh-cn_topic_0000001622194138_section1453415011">数据格式</a>章节。ND_ALIGN是矩阵的另一种数据格式，该格式一般用于N方向非32字节对齐的矩阵乘计算中，配置结果C矩阵为ND_ALIGN格式后，将按照N方向32字节对齐的补齐规则输出C矩阵，详细内容请见<a href="./../../../../编程指南/概念原理和术语/神经网络和算子/数据排布格式.html#li075920427155">ND_ALIGN</a>。</p><p>以M=16，K=16，N=14，A、B矩阵数据类型为half的Matmul为具体示例，说明ND_ALIGN输出功能。当配置C矩阵为ND格式并输出到Global Memory时，按照原始N方向大小非32字节对齐输出如<a href="#zh-cn_topic_0000002265055666_fig2311855162511">图1</a>所示。当配置C矩阵为ND格式时，按照N方向32字节对齐输出如<a href="#zh-cn_topic_0000002265055666_fig25741012182719">图2</a>所示，C矩阵的N方向最后两列由下一行的实际数据进行填充补齐，以实现N方向对齐到32字节并输出。当配置C矩阵为ND_ALIGN格式时，Matmul API会在C矩阵的N方向上通过添加无效数据来填充最后两列，以确保N方向对齐至32字节并输出，如<a href="#zh-cn_topic_0000002265055666_fig4840114152818">图3</a>所示。</p><p><strong>图 1</strong> ND格式C矩阵N方向非32字节对齐示意图<br><img src="'+l+'" alt="" title="ND格式C矩阵N方向非32字节对齐示意图"></p><p><strong>图 2</strong> ND格式C矩阵N方向32字节对齐示意图<br><img src="'+i+'" alt="" title="ND格式C矩阵N方向32字节对齐示意图"></p><p><strong>图 3</strong> ND_ALIGN格式C矩阵N方向32字节对齐示意图<br><img src="'+p+`" alt="" title="ND_ALIGN格式C矩阵N方向32字节对齐示意图"></p><h2 id="使用场景" tabindex="-1">使用场景 <a class="header-anchor" href="#使用场景" aria-label="Permalink to &quot;使用场景&quot;">​</a></h2><p>Matmul计算中N方向非32字节对齐，输出C矩阵的N方向要求32字节对齐的场景。</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>若配置C矩阵为ND_ALIGN格式输出，则为C矩阵申请的Buffer空间为N向上32字节对齐后的空间大小。</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>完整的算子样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_libraries/00_matrix/matmul_format_nd_align" target="_blank" rel="noreferrer">matmul_nd_align算子样例</a>。</p><ul><li><p>Tiling实现</p><p>调用SetCType接口，设置C矩阵的数据格式为CubeFormat::ND_ALIGN，其它Tiling实现与<a href="./../算子实现.html#zh-cn_topic_0000001622514006_li19113114819525">基础场景</a>相同。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>auto ascendcPlatform = platform_ascendc::PlatformAscendC(context-&gt;GetPlatformInfo());</span></span>
<span class="line"><span>matmul_tiling::MatmulApiTiling tiling(ascendcPlatform); </span></span>
<span class="line"><span>tiling.SetAType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT16); </span></span>
<span class="line"><span>tiling.SetBType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT16);  </span></span>
<span class="line"><span>// 设置C矩阵，buffer位置为GM，数据格式为ND_ALIGN</span></span>
<span class="line"><span>tiling.SetCType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND_ALIGN, matmul_tiling::DataType::DT_FLOAT);</span></span>
<span class="line"><span>tiling.SetBiasType(AscendC::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT);</span></span>
<span class="line"><span>... // 其他实现内容</span></span>
<span class="line"><span>optiling::TCubeTiling tilingData;   </span></span>
<span class="line"><span>int ret = tiling.GetTiling(tilingData);</span></span></code></pre></div></li><li><p>Kernel实现</p><p>相较于<a href="./../算子实现.html#zh-cn_topic_0000001622514006_li1032116474330">基础场景</a>，ND_ALIGN输出功能要求在创建Matmul对象时，设置模板参数cType的数据格式为CubeFormat::ND_ALIGN。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &quot;lib/matmul_intf.h&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, half&gt; aType; </span></span>
<span class="line"><span>typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, half&gt; bType; </span></span>
<span class="line"><span>// 设置模板参数cType的数据格式为ND_ALIGN</span></span>
<span class="line"><span>typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND_ALIGN, float&gt; cType; </span></span>
<span class="line"><span>typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, float&gt; biasType; </span></span>
<span class="line"><span>AscendC::Matmul&lt;aType, bType, cType, biasType&gt; mm;</span></span></code></pre></div></li></ul>`,14)])])}const h=t(o,[["render",r]]);export{d as __pageData,h as default};
